import subprocess, re, os
# collect all friend commits with Friend-Message: 1
allcommits=set()
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log','--format=%H',f'origin/friend/{b}'],text=True)
    for sha in out.split():
        # check message
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' in msg:
            allcommits.add((b,sha))
# collect transcribed shas from main worktree files
trans=set()
for root,_,files in os.walk('/tmp/ross-main'):
    for f in files:
        if f.endswith('.md') and re.match(r'E\d+\.md',f):
            txt=open(os.path.join(root,f)).read()
            for m in re.finditer(r'Source: friend/(\w+) @ ([0-9a-f]+)',txt):
                trans.add((m.group(1),m.group(2)))
print('total friend-msg commits:',len(allcommits))
print('transcribed:',len(trans))
missing=allcommits-trans
print('missing count:',len(missing))
for m in sorted(missing)[:50]:
    print('MISSING',m)
